create extension if not exists "pgcrypto";
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, email text, display_name text, plan text default 'free', credits int default 100, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists voice_projects(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, name text, type text default 'Voice', text_content text, language text default 'id', created_at timestamptz default now());
create table if not exists conversations(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, title text, created_at timestamptz default now());
create table if not exists conversation_messages(id uuid primary key default gen_random_uuid(), conversation_id uuid references conversations(id) on delete cascade, role text, content text, created_at timestamptz default now());
create table if not exists agents(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, name text, description text, personality text, instructions text, language text default 'id', voice text, memory_enabled boolean default false, is_published boolean default false, created_at timestamptz default now());
create table if not exists usage_logs(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, feature text, credits_used int default 1, created_at timestamptz default now());
alter table profiles enable row level security;
alter table voice_projects enable row level security;
alter table conversations enable row level security;
alter table conversation_messages enable row level security;
alter table agents enable row level security;
alter table usage_logs enable row level security;
create policy "own profile" on profiles for all using (auth.uid()=id);
create policy "own voice" on voice_projects for all using (auth.uid()=user_id);
create policy "own conv" on conversations for all using (auth.uid()=user_id);
create policy "own agents" on agents for all using (auth.uid()=user_id);
create policy "own usage" on usage_logs for all using (auth.uid()=user_id);
create policy "own messages" on conversation_messages for all using (exists (select 1 from conversations c where c.id=conversation_messages.conversation_id and c.user_id=auth.uid()));
